ting systems"}, {"id": "10a43f48-fd2d-4e2b-8d8e-4796a3f7a8fb", "type": "concept", "title": "Clap and count"}, {"id": "66890408-d510-4e7e-86bb-e761d5ad9425", "type": "concept", "title": "Conduct while reading"}, {"id": "6e31411a-7179-499f-9fdd-bbd88f757d9b", "type": "concept", "title": "Tempo control"}], "description": "Rhythmic reading becomes embodied through speaking, clapping, tapping, and conducting."}]}, {"id": "5ef1b5d0-554a-415a-a54a-387dcfa0e1bf", "type": "topic", "title": "Interval Recognition and Functional Hearing", "description": "Connects interval identification to tonal function, singing, notation, and real musical contexts.", "children": [{"id": "7aab7154-125c-4e09-865f-151bbf4224a7", "type": "subtopic", "title": "Sung intervals", "children": [{"id": "54ed9a97-210f-48ce-b4f0-3789063220ad", "type": "concept", "title": "Ascending intervals"}, {"id": "6107953d-202e-4c98-abfd-87b5e1a42056", "type": "concept", "title": "Descending intervals"}, {"id": "4ca9d260-73a6-46a0-b6a4-26868964e93d", "type": "concept", "title": "Within a key"}, {"id": "6bd75901-615e-4d15-8d0f-a466124e3f04", "type": "concept", "title": "From fixed reference pitches"}], "description": "Intervals become more reliable when students can produce them, not only label them."}, {"id": "1041d4bb-e6a0-4ab2-9714-a5bcf4b240a2", "type": "subtopic", "title": "Functional intervals", "children": [{"id": "c89eefab-605e-41b2-b0b7-073a3aa49f7d", "type": "concept", "title": "Tonic to scale degrees"}, {"id": "39dc2e2e-4f6b-4470-87dc-7ddf928366a0", "type": "concept", "title": "Leading-tone pull"}, {"id": "c953bde1-5041-4943-ae05-466c5fc40180", "type": "concept", "title": "Dominant relationships"}, {"id": "46907866-41de-443e-b0cb-db9c256ab173", "type": "concept", "title": "Melodic tendency"}], "description": "A professional ear hears how intervals behave inside tonal music."}, {"id": "2dca3e7c-3e3a-4e21-be7f-a1fe617a30a5", "type": "subtopic", "title": "Recognition strategies", "children": [{"id": "647a284f-